-- ============================================================
-- UPGRADE: Visibility to all players (existing + new joiners)
-- by mrdelord / added to Uhhhhhh Reanimate
-- ============================================================

local function WaitForCharacterReady(targetPlayer, timeout)
	timeout = timeout or 15
	local char = targetPlayer.Character
	if not char then
		local conn
		local done = false
		conn = targetPlayer.CharacterAdded:Connect(function(c)
			char = c
			done = true
			conn:Disconnect()
		end)
		local t = 0
		while not done and t < timeout do
			task.wait(0.1)
			t += 0.1
		end
	end
	if not char then return nil end
	-- wait for HumanoidRootPart and Humanoid
	local hrp = char:WaitForChild("HumanoidRootPart", timeout)
	local hum = char:WaitForChild("Humanoid", timeout)
	if not hrp or not hum then return nil end
	return char, hrp, hum
end

-- UPGRADE: Multi-method replication untuk semua tipe avatar
-- Method 1: firetouchinterest ke semua BasePart (bukan cuma HRP)
--   → handle avatar custom yang HRP-nya CanCollide=false
-- Method 2: semua Accessory handle (paid Robux items sering hanya sync lewat ini)
-- Method 3: repeat setelah jeda supaya server streaming catch up
local function ReplicateToPlayer(targetPlayer)
	if targetPlayer == Player then return end
	task.spawn(function()
		local char, hrp, hum = WaitForCharacterReady(targetPlayer)
		if not char then return end

		local myChar = Player.Character
		if not myChar then return end
		local myHrp = myChar:FindFirstChild("HumanoidRootPart")
		if not myHrp then return end

		-- Kumpulkan semua target part dari karakter lawan
		-- (HRP + Torso + semua Accessory Handle) supaya custom ava tetap sync
		local targetParts = {}
		-- selalu coba HRP dulu
		table.insert(targetParts, hrp)
		-- tambah Torso / UpperTorso untuk R6/R15
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
		if torso then table.insert(targetParts, torso) end
		-- tambah semua Accessory Handle (paid items sync lewat sini)
		for _, acc in char:GetChildren() do
			if acc:IsA("Accessory") then
				local h = acc:FindFirstChild("Handle")
				if h and h:IsA("BasePart") then
					table.insert(targetParts, h)
				end
			end
		end

		-- Kumpulkan semua source part dari karakter kita
		local sourceParts = {}
		table.insert(sourceParts, myHrp)
		local myTorso = myChar:FindFirstChild("Torso") or myChar:FindFirstChild("UpperTorso")
		if myTorso then table.insert(sourceParts, myTorso) end
		for _, acc in myChar:GetChildren() do
			if acc:IsA("Accessory") then
				local h = acc:FindFirstChild("Handle")
				if h and h:IsA("BasePart") then
					table.insert(sourceParts, h)
					break -- cukup 1 accessory sebagai source
				end
			end
		end

		-- Fire kombinasi source × target (paling reliable untuk paid items)
		local function firePair(src, tgt)
			if not src or not tgt then return end
			if not src:IsDescendantOf(workspace) then return end
			if not tgt:IsDescendantOf(workspace) then return end
			-- simpan state asli dan paksa CanTouch=true sementara
			local srcWas = src.CanTouch
			local tgtWas = tgt.CanTouch
			pcall(function() src.CanTouch = true end)
			pcall(function() tgt.CanTouch = true end)
			pcall(firetouchinterest, src, tgt, 0)
			task.wait(0.03)
			pcall(firetouchinterest, src, tgt, 1)
			pcall(function() src.CanTouch = srcWas end)
			pcall(function() tgt.CanTouch = tgtWas end)
		end

		-- Round 1: HRP vs HRP (standard)
		firePair(myHrp, hrp)
		task.wait(0.05)

		-- Round 2: semua source vs semua target (custom ava + paid accessories)
		for _, src in sourceParts do
			for _, tgt in targetParts do
				if src ~= myHrp or tgt ~= hrp then -- skip pair yang sudah difire
					firePair(src, tgt)
				end
			end
			task.wait(0.02)
		end

		-- Round 3: repeat setelah 1 detik untuk server streaming yang lambat
		task.wait(1)
		if char and char:IsDescendantOf(workspace) and myChar and myChar:IsDescendantOf(workspace) then
			firePair(myHrp, hrp)
			-- re-fire khusus accessories yang baru load
			for _, acc in char:GetChildren() do
				if acc:IsA("Accessory") then
					local h = acc:FindFirstChild("Handle")
					if h and h:IsA("BasePart") and h:IsDescendantOf(workspace) then
						firePair(myHrp, h)
					end
				end
			end
		end
	end)
end

local function SetupPlayerTracking(targetPlayer)
	if targetPlayer == Player then return end
	-- apply to their current character right now
	ReplicateToPlayer(targetPlayer)
	-- re-apply every time they respawn
	targetPlayer.CharacterAdded:Connect(function(newChar)
		-- Jeda 1.5 detik untuk karakter dasar load
		task.wait(1.5)
		ReplicateToPlayer(targetPlayer)
		-- Jeda tambahan untuk accessories paid Robux yang load lebih lambat
		-- (WrapLayer, MeshPart accessories butuh waktu lebih untuk streaming)
		task.wait(3)
		if newChar and newChar:IsDescendantOf(workspace) then
			ReplicateToPlayer(targetPlayer)
		end
	end)
end

-- re-apply to everyone when OUR OWN character respawns too
Player.CharacterAdded:Connect(function()
	-- Jeda 1.5 detik untuk karakter dasar load
	task.wait(1.5)
	for _, p in Players:GetPlayers() do
		ReplicateToPlayer(p)
	end
	-- Jeda tambahan untuk accessories paid yang lambat streaming
	task.wait(3)
	for _, p in Players:GetPlayers() do
		ReplicateToPlayer(p)
	end
end)

-- apply to all players already in the server right now
for _, p in Players:GetPlayers() do
	SetupPlayerTracking(p)
end

-- apply to every new player who joins after script loads
Players.PlayerAdded:Connect(function(p)
	SetupPlayerTracking(p)
end)

Util.Notify("Uhhhhhh: All-player visibility active! (Custom+Paid Ava Fix v2)")

