-- Mode:
--   0 = rootpart di void dalam (butuh streaming off, sering di-kick game modern)
--   1 = rootpart di bawah void
--   2 = rootpart di bawah karakter (AMAN, paling kompatibel)
--   3 = CurrentAngle style
--   4 = rootpart = torso (paling smooth, tapi bisa lag di game rame)
-- Velocity:
--   0 = tidak ada velocity (aman, tidak bikin fly)
--   1 = ikut fake character (bagus untuk battle)
--   2 = fling-y (terlalu agresif)
-- NaN: true = pakai NaN fling (lebih invisible di battle, tapi risiko kick di beberapa game)
-- Fling: true = bisa fling orang lain
local MRXN_PRESETS = {
	-- Battleground umum: Mode 2 + Velocity 1 + NaN supaya posisi tidak ketebak anti-cheat
	BATTLEGROUND = { Mode=2, Velocity=1, InitMode=2, NaN=true,  Fling=true,  Label="Battleground / PVP" },
	-- Open world battle (Blox Fruits, King Legacy): Mode 2, NaN off supaya tidak kena kick portal
	OPEN_WORLD   = { Mode=2, Velocity=1, InitMode=2, NaN=false, Fling=true,  Label="Open World / RPG" },
	-- Sword/melee: Mode 4 (rootpart=torso) supaya hitbox akurat
	SWORD        = { Mode=4, Velocity=1, InitMode=2, NaN=true,  Fling=true,  Label="Sword / Melee Fighting" },
	-- Shooter/FPS: Mode 2, NaN true supaya tidak keliatan ngambang
	SHOOTER      = { Mode=2, Velocity=1, InitMode=2, NaN=true,  Fling=true,  Label="Shooter / FPS" },
	-- Survive/disaster: tidak perlu fling, velocity 0 supaya tidak keliatan aneh
	SURVIVE      = { Mode=2, Velocity=0, InitMode=1, NaN=false, Fling=false, Label="Survive / Disaster" },
	-- Tower/obby: Mode 2, tidak fling supaya tidak kena kick
	TOWER        = { Mode=2, Velocity=0, InitMode=2, NaN=false, Fling=false, Label="Tower / Obby" },
	-- Default universal
	DEFAULT      = { Mode=2, Velocity=0, InitMode=2, NaN=false, Fling=true,  Label="Universal (default)" },
}

