	                                                                   preset="SWORD" },
	{ keys={"shooter","arsenal","frontline","sniper","fps","gun","shoot"},
	                                                                   preset="SHOOTER" },
	{ keys={"survive","disaster","killer","flee","hunt","escape","horror","piggy",
	        "apeiro","rainbow"},                                       preset="SURVIVE" },
	{ keys={"tower","obby","obstacle","parkour","toh","misery"},       preset="TOWER" },
}

local function MRXN_KeywordScan(str)
	if not str or #str == 0 then return nil end
	str = str:lower()
	for _, e in ipairs(MRXN_KEYWORDS) do
		for _, k in ipairs(e.keys) do
			if str:find(k, 1, true) then
				return MRXN_PRESETS[e.preset], e.preset
			end
		end
	end
	return nil
end

local function MRXN_Detect()
	local pid = game.PlaceId

	-- 1. PlaceId exact match (paling akurat)
	if MRXN_PLACEID[pid] then
		return MRXN_PRESETS[MRXN_PLACEID[pid]], MRXN_PLACEID[pid]
	end

	-- 2. game.Name (lebih reliable dari workspace.Name untuk game dengan map custom)
	local gname_direct = pcall(function() return game.Name end) and game.Name or ""
	local p, k = MRXN_KeywordScan(gname_direct)
	if p then return p, k end

	-- 3. workspace.Name
	p, k = MRXN_KeywordScan(workspace.Name)
	if p then return p, k end

	-- 4. MarketplaceService (async fallback, tidak block)
	local ok, info = pcall(function()
		return game:GetService("MarketplaceService"):GetProductInfo(pid)
	end)
	if ok and info then
		p, k = MRXN_KeywordScan(info.Name or "")
		if p then return p, k end
		p, k = MRXN_KeywordScan(info.Description or "")
		if p then return p, k end
	end

	-- 5. Cek beberapa nama folder di dalam workspace sebagai petunjuk
	-- (beberapa game punya folder "BattleSystem", "GunSystem", dll)
	local hints = ""
	for _, child in workspace:GetChildren() do
		hints = hints .. child.Name:lower() .. " "
		if #hints > 300 then break end -- jangan scan terlalu banyak
	end
	p, k = MRXN_KeywordScan(hints)
	if p then return p, k end

	return MRXN_PRESETS.DEFAULT, "DEFAULT"
end

local function MRXN_Apply(preset, silent)
	LimbReanimator.Mode         = preset.Mode
	LimbReanimator.Velocity     = preset.Velocity
	LimbReanimator.InitMode     = preset.InitMode
	LimbReanimator.UseNaNFling  = preset.NaN
	LimbReanimator.FlingEnabled = preset.Fling
	-- SaveData nil-safe (kadang SaveData.Reanimator belum init saat dipanggil awal)
	if SaveData and SaveData.Reanimator then
		SaveData.Reanimator.LimbMode        = preset.Mode
		SaveData.Reanimator.LimbVelocity    = preset.Velocity
		SaveData.Reanimator.LimbInitMode    = preset.InitMode
		SaveData.Reanimator.LimbUseNaNFling = preset.NaN
		SaveData.Reanimator.LimbRoleplay    = not preset.Fling
	end
	-- Boost SimulationRadius untuk game battleground/pvp supaya semua orang keliatan
	-- bahkan di server rame (20+ player)
	if preset.Fling then
		pcall(function()
			Player.SimulationRadius = 2e9
			pcall(sethiddenproperty, Player, "SimulationRadius", 2e9)
			pcall(sethiddenproperty, Player, "MaxSimulationRadius", 2e9)
		end)
	end
	if not silent then
		Util.Notify("MRXN: " .. preset.Label)
		pcall(function() Util.UINotify("🎮 " .. preset.Label) end)
	end
end

-- jalankan setelah script fully loaded
