	while not IsUhhhhhhFullyLoaded do task.wait(0.3) end
	local preset = MRXN_Detect()
	MRXN_Apply(preset, false)

	-- tambah panel di MainPage
	pcall(function()
		UI.CreateSeparator(MainPage)
		UI.CreateText(MainPage, "<b>🎮 MRXN GAME PATCH</b>", 14, Enum.TextXAlignment.Center)
		UI.CreateText(MainPage, preset.Label, 12, Enum.TextXAlignment.Center)
		local presetKeys   = {"BATTLEGROUND","OPEN_WORLD","SWORD","SHOOTER","SURVIVE","TOWER","DEFAULT"}
		local presetLabels = {
			"Battleground / PVP",
			"Open World / RPG",
			"Sword / Melee",
			"Shooter / FPS",
			"Survive / Disaster",
			"Tower / Obby",
			"Universal",
		}
		-- cari index preset yang sedang aktif untuk default dropdown
		local activeIdx = #presetKeys -- default ke Universal
		for i, k in presetKeys do
			if MRXN_PRESETS[k] == preset then
				activeIdx = i
				break
			end
		end
		UI.CreateDropdown(MainPage, "Force Preset", presetLabels, activeIdx).Changed:Connect(function(v)
			MRXN_Apply(MRXN_PRESETS[presetKeys[v]], false)
			-- restart reanimate supaya preset langsung aktif
			task.wait(0.3)
			if Reanimate and Reanimate.Character then
				pcall(Reanimate.CreateCharacter)
			end
		end)
		UI.CreateButton(MainPage, "Re-detect Game", 16).Activated:Connect(function()
			local p = MRXN_Detect()
			MRXN_Apply(p, false)
			if Reanimate and Reanimate.Character then
				pcall(Reanimate.CreateCharacter)
			end
		end)
	end)

	-- restart reanimate biar preset langsung aktif
	task.wait(0.5)
	if Reanimate and Reanimate.Character then
		pcall(Reanimate.CreateCharacter)
	end
end)

