-- Debug & shortcut via chat:
--   mrxninfo          → info preset aktif sekarang
--   mrxnset battle    → paksa preset BATTLEGROUND
--   mrxnset open      → paksa preset OPEN_WORLD
--   mrxnset sword     → paksa preset SWORD
--   mrxnset shoot     → paksa preset SHOOTER
--   mrxnset survive   → paksa preset SURVIVE
--   mrxnset tower     → paksa preset TOWER
--   mrxnset default   → paksa preset DEFAULT
pcall(function()
	local chatShortcuts = {
		["battle"]  = "BATTLEGROUND",
		["pvp"]     = "BATTLEGROUND",
		["open"]    = "OPEN_WORLD",
		["rpg"]     = "OPEN_WORLD",
		["sword"]   = "SWORD",
		["melee"]   = "SWORD",
		["shoot"]   = "SHOOTER",
		["fps"]     = "SHOOTER",
		["survive"] = "SURVIVE",
		["tower"]   = "TOWER",
		["obby"]    = "TOWER",
		["default"] = "DEFAULT",
	}
	TextChatService.MessageReceived:Connect(function(msg)
		if not (msg.TextSource and msg.TextSource.UserId == Player.UserId) then return end
		local text = (msg.Text or ""):lower():match("^%s*(.-)%s*$") -- trim
		if text == "mrxninfo" then
			local p, k = MRXN_Detect()
			Util.Notify(string.format(
				"PlaceId: %d\nDetected: %s\nActive: %s\nMode:%d Vel:%d Init:%d NaN:%s Fling:%s",
				game.PlaceId, tostring(k), tostring(p.Label),
				LimbReanimator.Mode, LimbReanimator.Velocity, LimbReanimator.InitMode,
				tostring(LimbReanimator.UseNaNFling), tostring(LimbReanimator.FlingEnabled)
			))
		elseif text:sub(1, 8) == "mrxnset " then
			local arg = text:sub(9):match("^%s*(.-)%s*$")
			local presetKey = chatShortcuts[arg]
			if presetKey and MRXN_PRESETS[presetKey] then
				MRXN_Apply(MRXN_PRESETS[presetKey], false)
				task.wait(0.3)
				if Reanimate and Reanimate.Character then
					pcall(Reanimate.CreateCharacter)
				end
			else
				Util.Notify("MRXN: preset '" .. arg .. "' tidak dikenal.\nCoba: battle, open, sword, shoot, survive, tower, default")
			end
		end
	end)
end)
